<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue'
import axios from 'axios'
interface Job{id:string;session_name:string;channel_id:string|null;status:string;error_code:string|null;next_run_at:string}
const folder=ref(''),jobs=ref<Job[]>([]),error=ref(''),message=ref(''),busy=ref(false),loaded=ref(false),dirty=ref(false)
const auth=()=>({headers:{Authorization:`Bearer ${localStorage.getItem('admin_token')}`}})
const labels:Record<string,string>={queued:'В очереди',running:'Выполняется',retry:'Ожидает повторения',blocked:'Требует внимания',ready:'✓ Подписка подтверждена',cancelled:'Отменено'}
const reasons:Record<string,string>={flood_wait:'Ограничение Telegram. Повторение после указанного времени.',invite_required:'Добавьте закрытый канал в общую папку или укажите приглашение при регистрации источника.',source_not_in_folder:'Канала нет в опубликованной папке. Обновите её состав и сохраните ссылку.',invite_expired:'Приглашение отозвано или истекло. Обновите ссылку.',approval_pending:'Заявка отправлена. После одобрения администратором канала повторите проверку.',telegram_channel_limit:'Достигнут лимит каналов Telegram.',node_unavailable:'Нет доступной Media Node. Задача сохранена.',session_not_connected:'Медиа-сессия ещё не подключилась на ноде.',access_denied:'Доступ запрещён Telegram.',authorization_required:'Повторно авторизуйте медиа-сессию.',telegram_unavailable:'Telegram временно недоступен.',source_unavailable:'Канал недоступен или его имя изменилось.',source_mismatch:'Приглашение относится к другому каналу.',account_busy:'Аккаунт выполняет другую задачу.',folder_channels_only:'Папка должна содержать только каналы и супергруппы.',folder_incomplete:'Telegram вернул неполный состав папки. Повторение автоматически.',membership_recheck:'Подписка уже существует; выполняется повторная проверка.',folder_changed:'Ссылка на папку изменена.'}
let timer:number|undefined
async function load(){try{const {data}=await axios.get('/api/v1/admin/media/membership',auth());jobs.value=data.jobs;if(!dirty.value)folder.value=data.folder_link;loaded.value=true;error.value=''}catch{error.value='Не удалось получить состояние подписок.'}}
async function save(){busy.value=true;error.value='';try{await axios.put('/api/v1/admin/media/membership',{folder_link:folder.value.trim()},auth());dirty.value=false;message.value='Сохранено. Медиа-сессии синхронизируются в фоне.';await load()}catch(e:any){error.value=e.response?.data?.detail||'Настройки не сохранены.'}finally{busy.value=false}}
async function retry(j:Job){busy.value=true;error.value='';try{await axios.post(`/api/v1/admin/media/membership/jobs/${j.id}/retry`,{},auth());await load()}catch(e:any){error.value=e.response?.data?.detail||'Повторение недоступно.'}finally{busy.value=false}}
onMounted(()=>{load();timer=window.setInterval(load,10000)});onUnmounted(()=>{if(timer)clearInterval(timer)})
</script>
<template><section class="membership-panel" aria-labelledby="membership-title">
<header><div><h2 id="membership-title">Автоматические подписки на каналы</h2><p>Master индексирует контент. Медиа-аккаунты вступают в источники через очередь на Media Node.</p></div><button type="button" @click="load">Обновить статусы</button></header>
<form @submit.prevent="save"><label for="membership-folder">Пригласительная ссылка на папку с каналами (Chat Folder Link)</label><div class="membership-input"><input id="membership-folder" v-model="folder" @input="dirty=true" type="url" maxlength="256" autocomplete="off" placeholder="https://t.me/addlist/..." :disabled="!loaded"/><button class="primary" :disabled="busy||!loaded">Сохранить и синхронизировать</button></div><small>Опубликуйте папку для совместного доступа. Сохранение запускает синхронизацию активных медиа-сессий. Пустое поле отключает импорт папки, но не подписки на новые доступные источники. Выход из каналов не выполняется.</small></form>
<p>Между задачами — 2–4 секунды. FloodWait сохраняется при перезапуске; ограничения и одобрение заявок Telegram не обходятся.</p>
<p v-if="error" class="problem" role="alert">{{error}}</p><p v-if="message" class="success" role="status">{{message}}</p>
<details v-if="jobs.length"><summary>Последние задачи подписки · {{jobs.length}} (до 200)</summary><div class="membership-jobs"><article v-for="j in jobs" :key="j.id" :class="`state-${j.status}`"><div><strong>{{j.session_name}}</strong><small>{{j.channel_id||'Импорт общей папки'}}</small></div><div><strong>{{labels[j.status]||j.status}}</strong><p v-if="j.error_code">{{reasons[j.error_code]||'Проверьте доступ и повторите задачу.'}}</p><small v-if="j.status==='retry'">Не ранее: {{new Date(j.next_run_at).toLocaleString()}}</small></div><button v-if="['blocked','retry'].includes(j.status)" type="button" :disabled="busy" @click="retry(j)">Повторить</button></article></div></details>
<p v-else>Задач пока нет. Они появятся после авторизации медиа-сессии, сохранения папки или добавления канала.</p>
</section></template>
<style scoped>
.membership-panel{display:grid;gap:18px;padding:24px;margin:24px 0;border:1px solid var(--ui-border,#334155);border-radius:14px;background:var(--ui-surface,#182231)}header{display:flex;justify-content:space-between;align-items:flex-start;gap:20px}h2{margin:0 0 8px}p{margin:6px 0;line-height:1.5}p,small{color:var(--ui-muted,#a8b7ca)}form{display:grid;gap:10px}.membership-input{display:flex;gap:12px}.membership-input input{flex:1;min-width:0}.membership-jobs{display:grid;gap:12px;margin-top:16px}.membership-jobs article{display:grid;grid-template-columns:minmax(110px,1fr) minmax(0,2fr) auto;gap:16px;padding:16px;border:1px solid var(--ui-border,#334155);border-radius:10px;overflow-wrap:anywhere}small{display:block;margin-top:6px;line-height:1.5}.state-blocked,.problem{border-left:3px solid #fb7185!important}.state-ready,.success{border-left:3px solid #34d399!important}.problem,.success{padding:12px 16px;background:#111d2c;border-radius:8px}.state-retry{border-left:3px solid #fbbf24!important}summary{cursor:pointer;font-weight:600}@media(max-width:760px){.membership-panel{padding:18px}header,.membership-input{flex-direction:column;align-items:stretch}.membership-jobs article{grid-template-columns:minmax(0,1fr)}button{white-space:normal}}
</style>
